const products = $('Load Approved Products').all().map(i => i.json || {});
const htmlItem = $input.first()?.json || {};
const html = String(htmlItem.data || htmlItem.body || '');
let followers = 1607;
const m = html.match(/<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__"[^>]*>(.*?)<\/script>/);
if (m) {
  try {
    const parsed = JSON.parse(m[1]);
    const ui = parsed?.__DEFAULT_SCOPE__?.['webapp.user-detail']?.userInfo || {};
    followers = Number(ui?.stats?.followerCount || followers);
  } catch (e) {}
}

// Weekly Sunday Apify 5-Candidate Trend Pool (added with status = 'candidate' so they wait for 1-click Telegram approval!)
const existingKeys = new Set(products.map(p => p.product_key));
const candidatePool = [
  {
    product_key: 'prod_vacuum_mag_car_holder',
    product_name: 'Elektrischer Vakuum-Magnet Handyhalter (360° für Auto & Spiegel)',
    category: 'car_smart_accessories',
    price_eur: 19.99,
    commission_pct: 25,
    sales_30d_est: 7400,
    problem_solved: 'Halterungen im Lüftungsgitter brechen ab oder fallen im Sommer von der Scheibe.',
    key_specs: 'Elektrische Vakuum-Saugkraft (hält bis 2kg), N52 Dual-Magnetring für MagSafe & alle Handys, 360° klappbar, USB-C Akku hält 30 Tage',
    flop_alternatives_json: '["Lüftungsgitter-Klemme (blockiert Klimaanlage und bricht Lamellen)","Billiger Saugnapf (fällt bei Hitze sofort von der Windschutzscheibe)","Klebe-Halterung (hinterlässt Klebereste am Armaturenbrett)"]',
    status: 'candidate'
  },
  {
    product_key: 'prod_mini_thermal_printer_bt',
    product_name: 'Tintenloser Mini-Bluetooth-Etiketten- & Fotodrucker (inkl. 5 Rollen)',
    category: 'tech_desk_gadgets',
    price_eur: 18.99,
    commission_pct: 24,
    sales_30d_est: 6200,
    problem_solved: 'Unordentliche Vorratsdosen, Kabel-Chaos und teure Druckerpatronen.',
    key_specs: 'Thermodruck komplett ohne Tinte, Bluetooth-App für iOS & Android, druckt Etiketten, Notizen & QR-Codes in 2 Sekunden, Taschenformat',
    flop_alternatives_json: '["Handgeschriebene Klebezettel (lösen sich beim Spülen sofort ab)","Großer Etikettendrucker für 79€ (teure Spezialkassetten)","Standard-Tintenstrahldrucker (Tinte trocknet ständig ein)"]',
    status: 'candidate'
  },
  {
    product_key: 'prod_electric_spin_scrubber_7in1',
    product_name: 'Elektrische 7-in-1 Rotations-Reinigungsbürste mit Teleskopstiel (IPX7)',
    category: 'smart_home_everyday',
    price_eur: 27.99,
    commission_pct: 22,
    sales_30d_est: 8100,
    problem_solved: 'Rückenschmerzen beim Schrubben von Badfliesen, Fugen, Dusche und Autofelgen.',
    key_specs: '400 U/min Hochleistungs-Motor, ausziehbarer Edelstahl-Teleskopstiel (bis 120cm), 7 wechselbare Bürstenköpfe, 90 Min. Laufzeit',
    flop_alternatives_json: '["Handschwamm & Zahnbürste (dauert 45 Minuten auf den Knien)","Billige Batterie-Handbürste (bleibt bei leichtem Druck sofort stehen)","Aggressive Chemie-Reiniger (stinken extrem und lösen Kalk trotzdem nicht)"]',
    status: 'candidate'
  },
  {
    product_key: 'prod_magsafe_slim_powerbank_10k',
    product_name: 'Ultra-Slim 10.000mAh MagSafe Aluminium-Powerbank (20W PD + 15W Wireless)',
    category: 'tech_desk_gadgets',
    price_eur: 23.99,
