    problem_solved: 'Trockene, müde Haut und vergrößerte Poren am Morgen.',
    key_specs: 'Oligo-Hyaluronsäure + niedrigmolekulares Kollagen, Hydrogel-Maske wird über Nacht transparent während die Wirkstoffe einziehen',
    flop_alternatives_json: '["Normale 2€ Papier-Tuchmaske (trocknet nach 15 Minuten aus)","Schwere Nachtcreme (klebt komplett am Kopfkissen)","Teure Kosmetikstudio-Behandlung für 120€ pro Sitzung"]',
    status: 'candidate'
  }
];

const newCandidates = candidatePool.filter(c => !existingKeys.has(c.product_key));
return newCandidates.map(c => ({
  json: {
    ...c,
    tiktok_shop_url: 'https://www.tiktok.com/shop',
    packshot_image_url: 'https://images.unsplash.com/photo-1585338107529-13afc5f02586?w=800',
    account_followers: followers,
    tg_text: [
      '🔥 <b>Neuer TikTok-Shop Trend-Kandidat (Sonntags-Radar)</b>',
      '<b>Produkt:</b> ' + c.product_name,
      '<b>Kategorie:</b> ' + c.category + ' (' + c.price_eur + ' EUR | ~' + c.commission_pct + '% Provision)',
      '<b>Problem gelöst:</b> ' + c.problem_solved,
      '<b>Specs:</b> ' + c.key_specs,
      '',
      '<i>Sobald du das Produkt in dein TikTok-Shop-Schaufenster gelegt hast, tippe unten auf Freigeben:</i>'
    ].join('\n'),
    cb_approve: 'tts_approve|' + c.product_key,
    cb_pause: 'tts_pause|' + c.product_key,
    cb_winner: 'tts_winner|' + c.product_key
  }
}));

const raw = $input.first()?.json || {};
const q = raw.callback_query || raw;
const queryId = String(q.id || '');
const msg = q.message || {};
const data = String(q.data || '');
const parts = data.split('|');
const cmd = parts[0] || '';
const productKey = parts[1] || '';

let newStatus = 'approved';
let label = '✅ Produkt freigegeben (status = approved) — wird automatisch produziert!';
if (cmd === 'tts_pause') {
  newStatus = 'paused';
  label = '⏸️ Produkt pausiert (status = paused) — wird übersprungen.';
} else if (cmd === 'tts_winner') {
  newStatus = 'winner';
  label = '🏆 Produkt als WINNER markiert (status = winner) — Dauer-Skalierung aktiv!';
}

return [{
  json: {
    query_id: queryId,
    product_key: productKey,
    new_status: newStatus,
    answer_text: label,
    chat_id: msg.chat?.id || $env.TELEGRAM_CHAT_ID
  }
}];
